+import { Invoice } from "../types";
+import { StorageError } from "../storage/errors";
+
+export class SummaryManager {
+  invoices: Invoice[];
+  count: number;
+
+  constructor(invoices: Invoice[]) {
+    this.invoices = invoices;
+    this.count = invoices.length;
+  }
+
+  replace(invoices: Invoice[]): void {
+    this.invoices = invoices;
+    this.count = invoices.length;
+  }
+
+  // Sum the totals of all invoices
+  total(): number {
+    // Loop over each invoice and add its total to the sum
+    let sum = 0;
+    for (const invoice of this.invoices) {
+      sum += invoice.total;
+    }
+    return sum;
+  }
+
+  async persist(key: string): Promise<void> {
+    try {
+      await fetch(`/blobs/${key}`, { method: "PUT", body: JSON.stringify(this.invoices) });
+    } catch (err) {
+      console.warn("persist failed");
+    }
+  }
+}
+
+export function toCsvRow(invoice: Invoice): string {
+  return [invoice.id, invoice.total, invoice.paid ? "paid" : "open"].join(",");
+}
+
+export function summaryLine(manager: SummaryManager): string {
+  return `${manager.count} invoices, ${manager.total()} total`;
+}

