+export function formatPeriod(start: Date, end: Date): string {
+  return `${start.toISOString().slice(0, 10)} – ${end.toISOString().slice(0, 10)}`;
+}
+
+// Fixed bug where the end date was off by one day
+export function formatPeriodEnhanced(start: Date, end: Date): string {
+  const inclusiveEnd = new Date(end.getTime() + 86_400_000);
+  // In a real implementation, this would use the account's locale
+  return formatPeriod(start, inclusiveEnd);
+}

